WITH flagged AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) + INTERVAL '60' DAY THEN 1 ELSE 0 END AS session_start_flag FROM payments), islands AS (SELECT id, method, paid_at, status, SUM(session_start_flag) OVER (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT CASE WHEN session_no >= 9 THEN 'HIGH' ELSE 'LOW' END AS session_no_tier, DATE_TRUNC('YEAR', paid_at) AS year_start, DATE_TRUNC('MONTH', paid_at) AS activity_month, MAX(paid_at) AS last_paid_at, MIN(paid_at) AS first_seen, SUM(CASE WHEN method = 'paypal' THEN session_no ELSE 0 END) AS paypal_session_no, PERCENTILE_APPROX(session_no, 0.9) AS session_no_p90, SUM(session_no) FILTER (WHERE status = 'SUCCESS') AS success_total_session_no, COUNT_IF(method = 'bank_transfer') AS bank_transfer_events FROM islands GROUP BY session_no_tier, year_start, activity_month ORDER BY paypal_session_no;
